insert into public.recipes
    (slug, title, emoji, description, total_minutes, difficulty, servings, published,
     source_name, source_url, license_name, attribution, modified_from_source)
values
    ('wikibooks_biscuits_iii', 'Biscuits III', '🍳', 'This recipe is adapted from the public domain cookbook Mrs. Beeton''s Book of Household Management.', 20, 'Easy', 18, true, 'Wikibooks Cookbook', 'https://en.wikibooks.org/w/index.php?title=Cookbook%3ABiscuits+III&oldid=4535494', 'CC BY-SA 4.0', 'Wikibooks contributors (see linked page history)', true),
    ('wikibooks_milk_toast_i', 'Milk Toast I', '🍞', 'This recipe, though of common domain, is provided in the food writer M.F.K. Fisher''s book An Alphabet for Gourmets under the title MILK TOAST for the Ill, Weak, Old, Very Young, or Weary.', 10, 'Very easy', 1, true, 'Wikibooks Cookbook', 'https://en.wikibooks.org/w/index.php?title=Cookbook%3AMilk+Toast+I&oldid=4511231', 'CC BY-SA 4.0', 'Wikibooks contributors (see linked page history)', true),
    ('wikibooks_cassava_pone', 'Cassava Pone', '🍽️', 'Cassava pone is a dessert originating in the Caribbean. This recipe is modified from one by Alica''s Pepperpot.', 120, 'Easy', 10, true, 'Wikibooks Cookbook', 'https://en.wikibooks.org/w/index.php?title=Cookbook%3ACassava+Pone&oldid=4631037', 'CC BY-SA 4.0', 'Wikibooks contributors (see linked page history)', true),
    ('wikibooks_pohe_spiced_flattened_rice', 'Pohe (Spiced Flattened Rice)', '🍚', 'Pohe is a very popular breakfast dish in the Indian states of Maharashtra, Gujarat and Madhya Pradesh.', 15, 'Easy', 1, true, 'Wikibooks Cookbook', 'https://en.wikibooks.org/w/index.php?title=Cookbook%3APohe+%28Spiced+Flattened+Rice%29&oldid=4633573', 'CC BY-SA 4.0', 'Wikibooks contributors (see linked page history)', true),
    ('wikibooks_potato_gratin', 'Potato Gratin', '🥔', 'Potato gratin is a wonderful dish that is easy to make. It is a good accompaniment for roast lamb or roast chicken, but is as delicious served on its own with a green salad.', 180, 'Easy', 4, true, 'Wikibooks Cookbook', 'https://en.wikibooks.org/w/index.php?title=Cookbook%3APotato+Gratin&oldid=4523312', 'CC BY-SA 4.0', 'Wikibooks contributors (see linked page history)', true),
    ('wikibooks_frijoles_antioquenos_colombian_bean_stew', 'Frijoles Antioqueños (Colombian Bean Stew)', '🍲', 'Antioqueño beans is an icon of Colombian food.', 60, 'Medium', 6, true, 'Wikibooks Cookbook', 'https://en.wikibooks.org/w/index.php?title=Cookbook%3AFrijoles+Antioque%C3%B1os+%28Colombian+Bean+Stew%29&oldid=4518615', 'CC BY-SA 4.0', 'Wikibooks contributors (see linked page history)', true),
    ('wikibooks_roast_turkey_with_stuffing', 'Roast Turkey with Stuffing', '🍗', 'Roast turkey usually forms the centerpiece of Thanksgiving in the United States. There are many recipes and methods for cooking whole turkeys. Below is one of the simplest and therefore one of the most traditional.', 240, 'Medium', 6, true, 'Wikibooks Cookbook', 'https://en.wikibooks.org/w/index.php?title=Cookbook%3ARoast+Turkey+with+Stuffing&oldid=4518719', 'CC BY-SA 4.0', 'Wikibooks contributors (see linked page history)', true),
    ('wikibooks_rendang_indonesian_beef_and_coconut_stew', 'Rendang (Indonesian Beef and Coconut Stew)', '🍲', 'Rendang is made from beef or water buffalo meat slowly cooked in coconut milk and spices. The coconut milk used in cooking turns into a delicious spicy sauce that is more delicious than the meat itself.', 180, 'Easy', 10, true, 'Wikibooks Cookbook', 'https://en.wikibooks.org/w/index.php?title=Cookbook%3ARendang+%28Indonesian+Beef+and+Coconut+Stew%29&oldid=4541096', 'CC BY-SA 4.0', 'Wikibooks contributors (see linked page history)', true),
    ('wikibooks_jam_sandwich', 'Jam Sandwich', '🥪', 'The jam sandwich is, as its name suggests, a sandwich filled with jam. It can be filled with any kind of jam.', 5, 'Very easy', 1, true, 'Wikibooks Cookbook', 'https://en.wikibooks.org/w/index.php?title=Cookbook%3AJam+Sandwich&oldid=4518258', 'CC BY-SA 4.0', 'Wikibooks contributors (see linked page history)', true),
    ('wikibooks_sylheti_biryani', 'Sylheti Biryani', '🍚', '| Rice| Meat recipes | Cuisine of India| Cuisine of Sylhet', 60, 'Medium', 4, true, 'Wikibooks Cookbook', 'https://en.wikibooks.org/w/index.php?title=Cookbook%3ASylheti+Biryani&oldid=4517374', 'CC BY-SA 4.0', 'Wikibooks contributors (see linked page history)', true),
    ('wikibooks_nigerian_rice_and_beans_jollof', 'Nigerian Rice and Beans Jollof', '🍚', 'Rice and beans jollof is a typical Nigerian food made from rice and beans. It is served with beef, chicken or moin moin.', 40, 'Easy', 3, true, 'Wikibooks Cookbook', 'https://en.wikibooks.org/w/index.php?title=Cookbook%3ANigerian+Rice+and+Beans+Jollof&oldid=4513639', 'CC BY-SA 4.0', 'Wikibooks contributors (see linked page history)', true),
    ('wikibooks_cucumber_and_radish_salad', 'Cucumber and Radish Salad', '🥗', 'This salad is very easy to make.', 10, 'Easy', 2, true, 'Wikibooks Cookbook', 'https://en.wikibooks.org/w/index.php?title=Cookbook%3ACucumber+and+Radish+Salad&oldid=4518123', 'CC BY-SA 4.0', 'Wikibooks contributors (see linked page history)', true),
    ('wikibooks_manhattan_clam_chowder_i', 'Manhattan Clam Chowder I', '🥔', 'According to Alton Brown, who pointed this out in the installment of his program Good Eats titled "Send In The Clams," the use of tomatoes instead of milk was initially the work of Portuguese immigrants in Rhode...', 90, 'Very easy', 6, true, 'Wikibooks Cookbook', 'https://en.wikibooks.org/w/index.php?title=Cookbook%3AManhattan+Clam+Chowder+I&oldid=4630304', 'CC BY-SA 4.0', 'Wikibooks contributors (see linked page history)', true),
    ('wikibooks_tahdiq_crisped_persian_rice', 'Tahdiq (Crisped Persian Rice)', '🍚', 'Tahdiq, or tahdig is a popular Persian way of preparing rice.', 60, 'Medium', 4, true, 'Wikibooks Cookbook', 'https://en.wikibooks.org/w/index.php?title=Cookbook%3ATahdiq+%28Crisped+Persian+Rice%29&oldid=4513062', 'CC BY-SA 4.0', 'Wikibooks contributors (see linked page history)', true)
on conflict (slug) do update set
    title = excluded.title,
    emoji = excluded.emoji,
    description = excluded.description,
    total_minutes = excluded.total_minutes,
    difficulty = excluded.difficulty,
    servings = excluded.servings,
    published = excluded.published,
    source_name = excluded.source_name,
    source_url = excluded.source_url,
    license_name = excluded.license_name,
    attribution = excluded.attribution,
    modified_from_source = excluded.modified_from_source,
    updated_at = now();

