insert into public.recipe_steps (recipe_id, step_number, instruction)
select r.id, v.step_number, v.instruction
from (values
    ('wikibooks_biscuits_iii', 1, 'Preheat the oven to . Grease a baking pan.'),
    ('wikibooks_biscuits_iii', 2, 'Beat the egg and milk together in a bowl.'),
    ('wikibooks_biscuits_iii', 3, 'Mix the other ingredients into the egg mixture to form a soft dough.'),
    ('wikibooks_biscuits_iii', 4, 'Roll out the dough to and cut out into very thin biscuits with a round cookie cutter.'),
    ('wikibooks_biscuits_iii', 5, 'Place the biscuits on the baking pan.'),
    ('wikibooks_biscuits_iii', 6, 'Bake for 6 minutes until golden.'),
    ('wikibooks_biscuits_iii', 7, 'Take the biscuits out of the oven and leave them to cool.'),
    ('wikibooks_milk_toast_i', 1, 'Heat the milk to the simmering point.'),
    ('wikibooks_milk_toast_i', 2, 'Generously butter the toast slices.'),
    ('wikibooks_milk_toast_i', 3, 'Heat a pretty bowl, deeper than it is wide. Break the hot buttered toast into it, pour the steaming but not boiling milk over it, sprinkle a little salt and pepper on the top, and serve at once.'),
    ('wikibooks_cassava_pone', 1, 'Preheat the oven to 350°F (180°C).'),
    ('wikibooks_cassava_pone', 2, 'Combine all the ingredients together, mixing well to incorporate.'),
    ('wikibooks_cassava_pone', 3, 'Transfer the mixture to a baking dish.'),
    ('wikibooks_cassava_pone', 4, 'Bake the cassava pone for 60 minutes until firm and golden.'),
    ('wikibooks_pohe_spiced_flattened_rice', 1, 'Moisten the pohe with cold water by putting in a bowl and holding under a slow running tap. Mix by hand, then drain excess water and set aside (take care not to soak too long or the pohe would turn pasty).'),
    ('wikibooks_pohe_spiced_flattened_rice', 2, 'Heat the oil in a frying pan until medium hot. Add the mustard seeds and let them crackle for a few seconds'),
    ('wikibooks_pohe_spiced_flattened_rice', 3, 'Add the turmeric powder and asafoetida and fry for a few seconds (take care not to burn the turmeric).'),
    ('wikibooks_pohe_spiced_flattened_rice', 4, 'Add the green chillies and fry for a few seconds.'),
    ('wikibooks_pohe_spiced_flattened_rice', 5, 'Add the chopped onion and lower the heat. Cover and cook for 2 minutes. The onions should turn soft but not brown.'),
    ('wikibooks_pohe_spiced_flattened_rice', 6, 'The pohe that was kept aside should have absorbed the excess moisture by now.'),
    ('wikibooks_pohe_spiced_flattened_rice', 7, 'Mix the pohe by hand so that the flakes do not stick together and add to the frying pan.'),
    ('wikibooks_pohe_spiced_flattened_rice', 8, 'Add salt to taste and stir the contents of the fry pay so that the yellow color of the turmeric is spread evenly through the pohe.'),
    ('wikibooks_pohe_spiced_flattened_rice', 9, 'Cover and cook for 5 minutes on low heat. Do not uncover during this time, as the pohe must cook in the steam.'),
    ('wikibooks_pohe_spiced_flattened_rice', 10, 'Stir and cook for another 1 minute uncovered.'),
    ('wikibooks_pohe_spiced_flattened_rice', 11, 'Serve in a bowl garnished with chopped coriander leaves.'),
    ('wikibooks_potato_gratin', 1, 'Preheat the oven to'),
    ('wikibooks_potato_gratin', 2, 'Slice the potatoes very thinly (about ⅛" thick), if possible using a mandoline to achieve evenness, and place them in some fresh water.'),
    ('wikibooks_potato_gratin', 3, 'Swish around the potatoes in the water to get rid of the starch, because that excess starch can make the dish a little unpleasant.'),
    ('wikibooks_potato_gratin', 4, 'Pour away the water and place the potatoes on a wooden surface. Then pat dry with a paper towel or kitchen towel, which is important because otherwise the remaining water will mix with the cream, causing curdling problems.'),
    ('wikibooks_potato_gratin', 5, 'Return the sliced potatoes to a bowl and add the cream and chopped garlic. Add a generous pinch of salt and some pepper.'),
    ('wikibooks_potato_gratin', 6, 'You can also add a few fresh herbs (thyme is particularly good) but this is up to you.'),
    ('wikibooks_potato_gratin', 7, 'Peel the zest of the lemon and add it to the mixture.'),
    ('wikibooks_potato_gratin', 8, 'Mix well, so the cream gives a good coating to all the potatoes.'),
    ('wikibooks_potato_gratin', 9, 'Pile the potatoes into a buttered, oven-proof dish. The size is if course difficult to gauge but the potatoes should not be layered more than about 4 thick.'),
    ('wikibooks_potato_gratin', 10, 'Grate a generous amount of cheese, and spread over the mixture.'),
    ('wikibooks_potato_gratin', 11, 'Pop it all into the oven and leave until the top layer of cheese and potatoes are brown and the cream is bubbling and running down the side of the dish. This will take about 40 minutes.'),
    ('wikibooks_potato_gratin', 12, 'For a final flourish before serving, grate a goodly amount of fresh nutmeg over the cheese.'),
    ('wikibooks_frijoles_antioquenos_colombian_bean_stew', 1, 'Wash beans and let hydrate overnight by covering with twice its volume of water.'),
    ('wikibooks_frijoles_antioquenos_colombian_bean_stew', 2, 'The next day, remove any floating beans.'),
    ('wikibooks_frijoles_antioquenos_colombian_bean_stew', 3, 'Heat the oil in a pressure cooker. Add scallions and let fry until they start to brown. Add tomato, cumin, broth cube, and allspice. This is called "hogao", a basic sauce for many Colombian dishes.'),
    ('wikibooks_frijoles_antioquenos_colombian_bean_stew', 4, 'Add 6 cups water, the beans, and plantain. Bring to a boil over medium heat.'),
    ('wikibooks_frijoles_antioquenos_colombian_bean_stew', 5, 'Cover the pressure cooker, and let cook for 30 minutes.'),
    ('wikibooks_frijoles_antioquenos_colombian_bean_stew', 6, 'Let cool, then open the pressure cooker.'),
    ('wikibooks_frijoles_antioquenos_colombian_bean_stew', 7, 'Check water level, add the meat if using, and cover again. Cook for another 30 minutes.'),
    ('wikibooks_frijoles_antioquenos_colombian_bean_stew', 8, 'Taste for salt. If you want a thicker mixture, you can cook uncovered over low heat.'),
    ('wikibooks_roast_turkey_with_stuffing', 1, 'Combine stuffing ingredients in a bowl and mix well.'),
    ('wikibooks_roast_turkey_with_stuffing', 2, 'Preheat oven to 325°F. Place the rack in the lowest position of the oven.'),
    ('wikibooks_roast_turkey_with_stuffing', 3, 'Remove the neck and giblets.'),
    ('wikibooks_roast_turkey_with_stuffing', 4, 'Rinse the turkey and pat it dry with paper towels.'),
    ('wikibooks_roast_turkey_with_stuffing', 5, 'Place the turkey, breast side up, on a rack in the roasting pan. Rub the skin with softened butter, and season with salt and pepper.'),
    ('wikibooks_roast_turkey_with_stuffing', 6, 'Fill the body cavity with stuffing.'),
    ('wikibooks_roast_turkey_with_stuffing', 7, 'Place a meat thermometer in the thickest part of one thigh.'),
    ('wikibooks_roast_turkey_with_stuffing', 8, 'Position an aluminum foil tent over the turkey.'),
    ('wikibooks_roast_turkey_with_stuffing', 9, 'Place the turkey in the oven and pour 2 cups of stock into the bottom of the roasting pan.'),
    ('wikibooks_roast_turkey_with_stuffing', 10, 'Roast the turkey for 2½ hours, basting the entire turkey every 30 minutes with the juices on the bottom of the pan. Add stock to the drippings as they become dry, about 1–2 cups at a time.'),
    ('wikibooks_roast_turkey_with_stuffing', 11, 'Remove aluminum foil tent.'),
    ('wikibooks_roast_turkey_with_stuffing', 12, 'Roast until the meat reaches 185°F and the stuffing reaches 165°F. This should take about 4 hours. If the stuffing isn''t done by the time the turkey is ready, scoop the stuffing out and bake it alone in the oven until it reaches the correct temperature.'),
    ('wikibooks_roast_turkey_with_stuffing', 13, 'Serve immediately.'),
    ('wikibooks_rendang_indonesian_beef_and_coconut_stew', 1, 'Using a food processor, grind together all the ingredients for the spice paste.'),
    ('wikibooks_rendang_indonesian_beef_and_coconut_stew', 2, 'Marinate meat with the spice paste for at least 1 hour.'),
    ('wikibooks_rendang_indonesian_beef_and_coconut_stew', 3, 'Heat the coconut milk over low heat until some oil rises to the surface (at least 20 minutes). Stir the coconut milk while it is cooking.'),
    ('wikibooks_rendang_indonesian_beef_and_coconut_stew', 4, 'Transfer the meat and spice paste mixture to a large wok or pot. Cover with 300 ml of the hot coconut milk.'),
    ('wikibooks_rendang_indonesian_beef_and_coconut_stew', 5, 'Stirring occasionally, cook over medium-low heat until half of the coconut milk has evaporated.'),
    ('wikibooks_rendang_indonesian_beef_and_coconut_stew', 6, 'Add another 100 ml hot coconut milk, and stir until almost all of the coconut milk has evaporated.'),
    ('wikibooks_rendang_indonesian_beef_and_coconut_stew', 7, 'Keep on adding coconut milk, 100 ml at a time, and cooking until the previous addition has evaporated.'),
    ('wikibooks_rendang_indonesian_beef_and_coconut_stew', 8, 'Cook until the meat is tender (at least 1½ hours) and almost all the liquid from the coconut milk has reduced to a spicy sauce.'),
    ('wikibooks_jam_sandwich', 1, 'Spread the jam onto the first slice of bread.'),
    ('wikibooks_jam_sandwich', 2, 'Put the second slice of bread on top of the side of bread you have put the jam on.'),
    ('wikibooks_sylheti_biryani', 1, 'Rinse the Basmati rice thoroughly and soak it in water for about 30 minutes. Drain the rice and set it aside.'),
    ('wikibooks_sylheti_biryani', 2, 'In a large, heavy-bottomed pan or pot, heat the ghee over medium heat.'),
    ('wikibooks_sylheti_biryani', 3, 'Add the whole cumin seeds, ginger-garlic paste, sliced onion, green cardamom, cinnamon pieces, bay leaves, cloves, and black peppercorns. Sauté until the onions turn golden brown and aromatic.'),
    ('wikibooks_sylheti_biryani', 4, 'Add your meat to the pan and cook until it''s no longer pink.'),
    ('wikibooks_sylheti_biryani', 5, 'Add the drained rice to the pan and stir well, ensuring it''s coated with the flavorful mixture.'),
    ('wikibooks_sylheti_biryani', 6, 'Pour in enough water to cover the rice (typically about 4 cups of water for 2 cups of rice). Season with salt according to your taste.'),
    ('wikibooks_sylheti_biryani', 7, 'Bring the mixture to a boil, then reduce the heat to low, cover the pot, and let it simmer for about 15–20 minutes or until the rice is cooked and the water is absorbed.'),
    ('wikibooks_sylheti_biryani', 8, 'While the rice is cooking, make shallow cuts (slits) on the green chilies to release their flavor.'),
    ('wikibooks_sylheti_biryani', 9, 'Once the rice is done, remove it from heat and let it sit, covered, for a few more minutes to allow the flavors to meld.'),
    ('wikibooks_sylheti_biryani', 10, 'Serve the aromatic Sylheti biryani hot, garnished with the slitted green chilies, a dash of Kewra water, and a sprinkle of rose water for a delightful touch.'),
    ('wikibooks_nigerian_rice_and_beans_jollof', 1, 'Rinse the beans, and boil in water until tender. Drain the cooked beans.'),
    ('wikibooks_nigerian_rice_and_beans_jollof', 2, 'Grind together the chiles, tomatoes, and onions to make a purée.'),
    ('wikibooks_nigerian_rice_and_beans_jollof', 3, 'Heat a thin layer of oil in a pan, and add the purée. Season with stock cube and salt, and simmer for 3 minutes.'),
    ('wikibooks_nigerian_rice_and_beans_jollof', 4, 'Stir in the parboiled rice and beans, and cook for 5 minutes.'),
    ('wikibooks_nigerian_rice_and_beans_jollof', 5, 'Serve with beef, chicken, or moin-moin.'),
    ('wikibooks_cucumber_and_radish_salad', 1, 'Chop cucumbers and radishes into small cubes (about ¼ inch on the side).'),
    ('wikibooks_cucumber_and_radish_salad', 2, 'Chop green onions.'),
    ('wikibooks_cucumber_and_radish_salad', 3, 'Combine all of the above in an appropriately sized bowl.'),
    ('wikibooks_cucumber_and_radish_salad', 4, 'Add sour cream and mix well.'),
    ('wikibooks_cucumber_and_radish_salad', 5, 'Add salt to taste and mix again.'),
    ('wikibooks_manhattan_clam_chowder_i', 1, 'Core the tomatoes. Remove the pale parts and the seeds; the "meat" of the tomato will be what will be used. For canned tomatoes, a strainer will be helpful.'),
    ('wikibooks_manhattan_clam_chowder_i', 2, 'Chop all non-clam ingredients to match the clams in size.'),
    ('wikibooks_manhattan_clam_chowder_i', 3, 'If desired add spices. Suggestions offered include dill seed, basil, thyme, celery seed, tarragon, marjoram, and/or fresh cilantro. Alternatively, oregano can be used in lieu of the marjoram.'),
    ('wikibooks_manhattan_clam_chowder_i', 4, 'Cook the chowder, without boiling, until the celery begins to soften.'),
    ('wikibooks_tahdiq_crisped_persian_rice', 1, 'Peel and slice the raw potatoes into ½ inch thick slices.'),
    ('wikibooks_tahdiq_crisped_persian_rice', 2, 'Rinse and drain rice. Bring 4–5 cups of water to a boil in a 3-quart pot, adding salt if desired. Add rice, and continue to boil the water, stirring occasionally, for about 10 minutes. Check to be sure that the rice doesn''t cook completely at this point.'),
    ('wikibooks_tahdiq_crisped_persian_rice', 3, 'When rice is roughly half cooked, drain into a colander.'),
    ('wikibooks_tahdiq_crisped_persian_rice', 4, 'Pour ¼ cup of cooking oil into the pot and lay the potato slices in the bottom close together in a single layer. Add a small amount of salt (if desired). Layer the half-cooked, drained rice loosely atop the potatoes.'),
    ('wikibooks_tahdiq_crisped_persian_rice', 5, 'Place pot on stove over medium high heat for 4–5 minutes or until rice begins to steam.'),
    ('wikibooks_tahdiq_crisped_persian_rice', 6, 'Lower heat and add 5 tbsp water and 2–3 tbsp oil on top of rice. Cover and let simmer for about ½ hour or until cooked and tender. The higher the heat, the crunchier the tahdig.'),
    ('wikibooks_tahdiq_crisped_persian_rice', 7, 'Scoop out the rice and use a soft spatula to remove tahdig at bottom, or try to make the contents of the pot come out as an entire cake of rice on the serving dish.')
) as v(recipe_slug, step_number, instruction)
join public.recipes r on r.slug = v.recipe_slug;

